#include <fstream>
#include <iostream>
#include <limits>
#include <vector>
using namespace Aevrynd;

struct FrameSample3D{uint64_t wall{},cpu{},present{},gpu{};};
struct Samples3D{std::vector<uint64_t> mutableWall,frozenWall,mutableCpu,frozenCpu,mutablePresent,frozenPresent,mutableGpu,frozenGpu;size_t frozenWins{},cpuWins{};};
static uint64_t Percentile(std::vector<uint64_t> values,size_t percentile){std::ranges::sort(values);return values[(values.size()-1)*percentile/100];}
static uint64_t HashFile(const std::filesystem::path& path){std::ifstream input(path,std::ios::binary);uint64_t hash=1469598103934665603ull;char value{};while(input.get(value)){hash^=uint8_t(value);hash*=1099511628211ull;}return hash;}
static uint64_t CaptureTelemetryHash(const RendererStats& stats){uint64_t hash=1469598103934665603ull;for(double value:{stats.lastCapturedAverageLuminance,stats.lastCapturedLuminanceVariance,stats.lastCapturedDarkPixelFraction,stats.lastCapturedBrightPixelFraction}){hash^=uint64_t(std::llround(value*1000000.));hash*=1099511628211ull;}return hash;}
static FrameSample3D Sample(D3D12Renderer& renderer,const DrawList& draw){const auto begin=std::chrono::steady_clock::now();renderer.Render(draw,{0,0,0,1});const auto end=std::chrono::steady_clock::now();renderer.WaitIdle();const auto stats=renderer.GetStats();return{uint64_t(std::chrono::duration_cast<std::chrono::nanoseconds>(end-begin).count()),stats.lastRenderPreparationCpuNanoseconds+stats.lastRenderCommandRecordingCpuNanoseconds,stats.lastRenderPresentCpuNanoseconds,stats.lastGpuFrameNanoseconds};}
static bool Benchmark(D3D12Renderer& mutableRenderer,D3D12Renderer& frozenRenderer,std::span<const MeshHandle3D> mutableMeshes,std::span<const MeshHandle3D> frozenMeshes,size_t groupCount){
    DrawList mutableDraw;Camera3D camera{{0,0,-12},{0,0,0},{0,1,0},{}};mutableDraw.SetViewProjection(CreateViewProjectionMatrix(camera,640.f/360.f));
    DrawList frozenDraw;frozenDraw.SetViewProjection(mutableDraw.ViewProjection());for(size_t group=0;group<groupCount;++group)for(size_t item=0;item<8;++item){const bool rejected=(group+item*3)%7==0;const Vec3 position{rejected?(group&1?1000.f:-1000.f):float(int(group%32)-16)*.12f,float(int(group/32)-16)*.1f,float(item)*.02f};if(!mutableDraw.MeshInstance(mutableMeshes[group],CreateTranslationMatrix(position),{1,1,1,1},{},MeshRenderLayer3D::Opaque,{},.25f,false,MaterialClass3D::Surface,std::numeric_limits<float>::quiet_NaN(),false,1,0,false,DirectionalShadowAllCascades3D,ShadowCascadeSelection3D::Automatic,Matrix4::Identity(),false,1.f,MaterialAlphaMode3D::Opaque,.5f,group>=groupCount/2)||!frozenDraw.MeshInstance(frozenMeshes[group],CreateTranslationMatrix(position),{1,1,1,1},{},MeshRenderLayer3D::Opaque,{},.25f,false,MaterialClass3D::Surface,std::numeric_limits<float>::quiet_NaN(),false,1,0,false,DirectionalShadowAllCascades3D,ShadowCascadeSelection3D::Automatic,Matrix4::Identity(),false,1.f,MaterialAlphaMode3D::Opaque,.5f,group>=groupCount/2))return false;}
    frozenDraw.SetStaticMeshSubmission3D(frozenDraw.FreezeMeshInstances3D());
    for(size_t warm=0;warm<8;++warm){Sample(mutableRenderer,mutableDraw);Sample(frozenRenderer,frozenDraw);}Samples3D samples;
    for(size_t sample=0;sample<101;++sample){FrameSample3D mutableFrame{},frozenFrame{};if(sample&1){frozenFrame=Sample(frozenRenderer,frozenDraw);mutableFrame=Sample(mutableRenderer,mutableDraw);}else{mutableFrame=Sample(mutableRenderer,mutableDraw);frozenFrame=Sample(frozenRenderer,frozenDraw);}samples.mutableWall.push_back(mutableFrame.wall);samples.frozenWall.push_back(frozenFrame.wall);samples.mutableCpu.push_back(mutableFrame.cpu);samples.frozenCpu.push_back(frozenFrame.cpu);samples.mutablePresent.push_back(mutableFrame.present);samples.frozenPresent.push_back(frozenFrame.present);if(mutableFrame.gpu&&frozenFrame.gpu){samples.mutableGpu.push_back(mutableFrame.gpu);samples.frozenGpu.push_back(frozenFrame.gpu);}samples.frozenWins+=frozenFrame.wall<mutableFrame.wall;samples.cpuWins+=frozenFrame.cpu<mutableFrame.cpu;}
    // 中文註解：額外走完三個 frame slot，驗證 benchmark 最終讀到真正的 warm slot。
    for(size_t frame=0;frame<D3D12Renderer::BufferedFrames+1;++frame)Sample(frozenRenderer,frozenDraw);const auto stats=frozenRenderer.GetStats();
    // 中文註解：兩個 renderer 分別請求 validation，跨越所有 frame slot 後比較每群組可見數與 transform identity。
    if(!mutableRenderer.RequestGpuInstanceCullingValidationReadback3D()||!frozenRenderer.RequestGpuInstanceCullingValidationReadback3D())return false;for(size_t frame=0;frame<D3D12Renderer::BufferedFrames+2;++frame){Sample(mutableRenderer,mutableDraw);Sample(frozenRenderer,frozenDraw);}const auto mutableValidation=mutableRenderer.GetStats(),frozenValidation=frozenRenderer.GetStats();
    const bool asymmetric=std::ranges::any_of(mutableValidation.lastGpuInstanceCullingGroupVisible,[](uint32_t value){return value>0&&value<8;});
    const auto temporary=std::filesystem::temp_directory_path();const auto mutableCapture=temporary/("aevrynd-static-cache-mutable-"+std::to_string(groupCount)+".png"),frozenCapture=temporary/("aevrynd-static-cache-frozen-"+std::to_string(groupCount)+".png");std::filesystem::remove(mutableCapture);std::filesystem::remove(frozenCapture);if(!mutableRenderer.CaptureNextFrame(mutableCapture)||!frozenRenderer.CaptureNextFrame(frozenCapture))return false;Sample(mutableRenderer,mutableDraw);Sample(frozenRenderer,frozenDraw);const auto mutableCaptureStats=mutableRenderer.GetStats(),frozenCaptureStats=frozenRenderer.GetStats();const bool capturesValid=std::filesystem::is_regular_file(mutableCapture)&&std::filesystem::is_regular_file(frozenCapture)&&std::filesystem::file_size(mutableCapture)>1024&&std::filesystem::file_size(frozenCapture)>1024;const uint64_t mutableFileHash=capturesValid?HashFile(mutableCapture):0,frozenFileHash=capturesValid?HashFile(frozenCapture):0,mutableTelemetryHash=CaptureTelemetryHash(mutableCaptureStats),frozenTelemetryHash=CaptureTelemetryHash(frozenCaptureStats);std::filesystem::remove(mutableCapture);std::filesystem::remove(frozenCapture);
    const uint64_t mutableMedian=Percentile(samples.mutableWall,50),frozenMedian=Percentile(samples.frozenWall,50),mutableP95=Percentile(samples.mutableWall,95),frozenP95=Percentile(samples.frozenWall,95);const double medianGain=1.-double(frozenMedian)/double(mutableMedian),p95Gain=1.-double(frozenP95)/double(mutableP95),winRate=double(samples.frozenWins)/101.;
    const uint64_t mutableCpuMedian=Percentile(samples.mutableCpu,50),frozenCpuMedian=Percentile(samples.frozenCpu,50),mutableCpuP95=Percentile(samples.mutableCpu,95),frozenCpuP95=Percentile(samples.frozenCpu,95);const double cpuMedianGain=1.-double(frozenCpuMedian)/double(mutableCpuMedian),cpuP95Gain=1.-double(frozenCpuP95)/double(mutableCpuP95),cpuWinRate=double(samples.cpuWins)/101.;
    const uint64_t mutableGpuMedian=samples.mutableGpu.empty()?0:Percentile(samples.mutableGpu,50),frozenGpuMedian=samples.frozenGpu.empty()?0:Percentile(samples.frozenGpu,50);const double gpuRegression=mutableGpuMedian?double(frozenGpuMedian)/double(mutableGpuMedian)-1.:std::numeric_limits<double>::infinity();
    const bool validationParity=asymmetric&&mutableValidation.lastGpuInstanceCullingGroupVisible==frozenValidation.lastGpuInstanceCullingGroupVisible&&mutableValidation.lastGpuInstanceCullingGroupIdentityHashes==frozenValidation.lastGpuInstanceCullingGroupIdentityHashes&&!mutableValidation.gpuInstanceCullingValidationReadbackBytes&&!frozenValidation.gpuInstanceCullingValidationReadbackBytes;
    std::cout<<"groups="<<groupCount<<" instances="<<groupCount*8<<" mutable_median_ns="<<mutableMedian<<" frozen_median_ns="<<frozenMedian<<" median_gain="<<medianGain<<" mutable_p95_ns="<<mutableP95<<" frozen_p95_ns="<<frozenP95<<" p95_gain="<<p95Gain<<" win_rate="<<winRate<<" mutable_cpu_median_ns="<<mutableCpuMedian<<" frozen_cpu_median_ns="<<frozenCpuMedian<<" cpu_median_gain="<<cpuMedianGain<<" mutable_cpu_p95_ns="<<mutableCpuP95<<" frozen_cpu_p95_ns="<<frozenCpuP95<<" cpu_p95_gain="<<cpuP95Gain<<" cpu_win_rate="<<cpuWinRate<<" mutable_gpu_ns="<<mutableGpuMedian<<" frozen_gpu_ns="<<frozenGpuMedian<<" gpu_regression="<<gpuRegression<<" validation_parity="<<validationParity<<" capture_hash="<<mutableFileHash<<" telemetry_hash="<<mutableTelemetryHash<<" warm="<<stats.lastStaticMeshSubmissionWarmHit<<" copied_bytes="<<(stats.lastStaticMeshSubmissionInstanceCopiedBytes+stats.lastStaticMeshSubmissionGroupCopiedBytes+stats.lastStaticMeshSubmissionCommandCopiedBytes)<<'\n';
    return stats.lastStaticMeshSubmissionWarmHit&&!stats.lastStaticMeshSubmissionCpuRebuild&&!stats.lastStaticMeshSubmissionInstanceCopiedBytes&&!stats.lastStaticMeshSubmissionGroupCopiedBytes&&!stats.lastStaticMeshSubmissionCommandCopiedBytes&&samples.frozenWins>=51&&cpuMedianGain>=.25&&cpuP95Gain>=.25&&cpuWinRate>=.70&&mutableGpuMedian&&gpuRegression<=.05&&validationParity&&capturesValid&&mutableFileHash&&mutableFileHash==frozenFileHash&&mutableTelemetryHash&&mutableTelemetryHash==frozenTelemetryHash&&mutableCaptureStats.successfulFrameCaptures&&frozenCaptureStats.successfulFrameCaptures;
}
int main(){HINSTANCE instance=GetModuleHandleW(nullptr);WNDCLASSW wc{};wc.lpfnWndProc=DefWindowProcW;wc.hInstance=instance;wc.lpszClassName=L"AevryndGpuStaticSubmissionCacheBenchmark";RegisterClassW(&wc);HWND mutableWindow=CreateWindowW(wc.lpszClassName,L"GPU mutable baseline",WS_OVERLAPPED,0,0,640,360,nullptr,nullptr,instance,nullptr),frozenWindow=CreateWindowW(wc.lpszClassName,L"GPU frozen cache",WS_OVERLAPPED,0,0,640,360,nullptr,nullptr,instance,nullptr);if(!mutableWindow||!frozenWindow)return 1;D3D12Renderer mutableRenderer,frozenRenderer;for(auto* renderer:{&mutableRenderer,&frozenRenderer}){renderer->Initialize(renderer==&mutableRenderer?mutableWindow:frozenWindow,640,360,640,360,false);renderer->SetQualitySettings({false,false,false,false});renderer->SetGpuInstanceCullingSettings({true,500.f,GpuInstanceSubmissionMode3D::MultiGroup});}const Mesh3D source=Mesh3D::CreateUnitBox();std::vector<MeshHandle3D> mutableMeshes,frozenMeshes;for(size_t group=0;group<1024;++group){Mesh3D unique=source;unique.vertices[0].x+=float(group+1)*.00001f;const auto mutableMesh=mutableRenderer.CreateMesh(unique.vertices,unique.indices),frozenMesh=frozenRenderer.CreateMesh(unique.vertices,unique.indices);if(!mutableMesh||!frozenMesh)return 2;mutableMeshes.push_back(mutableMesh);frozenMeshes.push_back(frozenMesh);}const bool small=Benchmark(mutableRenderer,frozenRenderer,mutableMeshes,frozenMeshes,256),large=Benchmark(mutableRenderer,frozenRenderer,mutableMeshes,frozenMeshes,1024);for(auto mesh:mutableMeshes)mutableRenderer.DestroyMesh(mesh);for(auto mesh:frozenMeshes)frozenRenderer.DestroyMesh(mesh);mutableRenderer.WaitIdle();frozenRenderer.WaitIdle();DestroyWindow(mutableWindow);DestroyWindow(frozenWindow);return small&&large?0:3;}
